import { useState } from 'react'
import { ListCard } from './ListCard'
import { CreateListFormWrapper } from './CreateListFormWrapper'
import { EditListFormWrapper } from './EditListFormWrapper'
import { DeleteListDialog } from './DeleteListDialog'
import { Button } from '@/components/ui/button'
import { Plus, Package } from 'lucide-react'
import type { List, GearItem, WeightUnit } from '@/types/database'

interface ListsViewProps {
  lists: List[]
  gearItems: GearItem[] // All gear items for weight calculations
  weightUnit?: WeightUnit
  onCreateList: (data: Omit<List, 'id' | 'user_id' | 'created_at' | 'updated_at'>) => void
  onEditList: (id: string, updates: Partial<Omit<List, 'id' | 'user_id' | 'created_at' | 'updated_at'>>) => void
  onDeleteList: (id: string) => void
  onDuplicateList: (listId: string, newName: string) => void
  onViewList: (list: List) => void
  loading?: boolean
}

export function ListsView({
  lists,
  gearItems,
  weightUnit = 'g',
  onCreateList,
  onEditList,
  onDeleteList,
  onDuplicateList,
  onViewList,
  loading = false
}: ListsViewProps) {
  const [showCreateForm, setShowCreateForm] = useState(false)
  const [editingList, setEditingList] = useState<List | null>(null)
  const [deletingList, setDeletingList] = useState<List | null>(null)

  const handleCreateList = async (data: Omit<List, 'id' | 'user_id' | 'created_at' | 'updated_at'>) => {
    await onCreateList(data)
    setShowCreateForm(false)
  }

  const handleEditList = async (id: string, updates: Partial<Omit<List, 'id' | 'user_id' | 'created_at' | 'updated_at'>>) => {
    await onEditList(id, updates)
    setEditingList(null)
  }

  const handleDeleteList = async (list: List) => {
    await onDeleteList(list.id)
    setDeletingList(null)
  }

  const handleDuplicateList = async (list: List) => {
    const newName = `${list.name} (Copy)`
    await onDuplicateList(list.id, newName)
  }

  if (lists.length === 0 && !loading) {
    return (
      <>
        <div className="text-center py-12">
          <div className="mx-auto w-24 h-24 bg-muted rounded-full flex items-center justify-center mb-6">
            <Package className="w-12 h-12 text-muted-foreground/50" />
          </div>
          <h3 className="text-xl font-semibold mb-2">No lists yet</h3>
          <p className="text-muted-foreground mb-6 max-w-sm mx-auto">
            Create your first list to start organizing gear for different adventures and trips.
          </p>
          <Button
            onClick={() => setShowCreateForm(true)}
            className="bg-primary hover:bg-primary/90"
          >
            <Plus className="w-4 h-4 mr-2" />
            Create Your First List
          </Button>
        </div>

        {/* Create Form */}
        {showCreateForm && (
          <CreateListFormWrapper
            isOpen={showCreateForm}
            onCreate={handleCreateList}
            onCancel={() => setShowCreateForm(false)}
          />
        )}
      </>
    )
  }

  return (
    <>
      <div className="space-y-6">
        {/* Header with Create Button */}
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
          <div>
            <h2 className="text-2xl font-bold">Your Lists</h2>
            <p className="text-muted-foreground">
              {lists.length} list{lists.length !== 1 ? 's' : ''} • Organize gear for different adventures
            </p>
          </div>
          <Button
            onClick={() => setShowCreateForm(true)}
            className="bg-primary hover:bg-primary/90"
            disabled={loading}
          >
            <Plus className="w-4 h-4 mr-2" />
            Create List
          </Button>
        </div>

        {/* Lists Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {lists.map((list) => (
            <ListCard
              key={list.id}
              list={list}
              gearItems={gearItems}
              weightUnit={weightUnit}
              onView={onViewList}
              onEdit={setEditingList}
              onDelete={setDeletingList}
              onDuplicate={handleDuplicateList}
            />
          ))}
        </div>
      </div>

      {/* Create Form */}
      {showCreateForm && (
        <CreateListFormWrapper
          isOpen={showCreateForm}
          onCreate={handleCreateList}
          onCancel={() => setShowCreateForm(false)}
        />
      )}

      {/* Edit Form */}
      {editingList && (
        <EditListFormWrapper
          isOpen={!!editingList}
          list={editingList}
          onEdit={handleEditList}
          onCancel={() => setEditingList(null)}
        />
      )}

      {/* Delete Dialog */}
      {deletingList && (
        <DeleteListDialog
          list={deletingList}
          onConfirm={() => handleDeleteList(deletingList)}
          onCancel={() => setDeletingList(null)}
        />
      )}
    </>
  )
}

import { Button } from '@/components/ui/button'
import { 
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { TableProperties, LayoutList, LayoutGrid } from 'lucide-react'
import type { ViewMode } from '@/pages/GearCloset'

interface ViewModeSelectorProps {
  value: ViewMode
  onChange: (mode: ViewMode) => void
}

export function ViewModeSelector({ value, onChange }: ViewModeSelectorProps) {
  const modes: { value: ViewMode; label: string; icon: React.ReactNode; description: string }[] = [
    {
      value: 'compact',
      label: 'Compact',
      icon: <TableProperties className="h-4 w-4" />,
      description: 'Spreadsheet-style view with minimal spacing'
    },
    {
      value: 'default',
      label: 'Default',
      icon: <LayoutList className="h-4 w-4" />,
      description: 'Balanced view with essential information'
    },
    {
      value: 'comfortable',
      label: 'Comfortable',
      icon: <LayoutGrid className="h-4 w-4" />,
      description: 'Card view with rich details and visuals'
    }
  ]

  const currentMode = modes.find(m => m.value === value) || modes[1]

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button variant="outline" size="sm" className="gap-2 min-h-[44px]">
          {currentMode.icon}
          <span className="ml-2">{currentMode.label}</span>
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="w-64">
        {modes.map(mode => (
          <DropdownMenuItem
            key={mode.value}
            onClick={() => onChange(mode.value)}
            className="flex flex-col items-start py-3 cursor-pointer"
          >
            <div className="flex items-center space-x-2 mb-1">
              {mode.icon}
              <span className="font-medium">{mode.label}</span>
              {mode.value === value && (
                <span className="ml-auto text-xs bg-primary/10 text-primary px-2 py-0.5 rounded">
                  Active
                </span>
              )}
            </div>
            <span className="text-xs text-muted-foreground">
              {mode.description}
            </span>
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { 
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
  DropdownMenuSeparator,
} from '@/components/ui/dropdown-menu'
import { Filter, ChevronDown, Check } from 'lucide-react'

interface CategoryFilterDropdownProps {
  categories: string[]
  selectedCategory: string | null
  onSelectCategory: (category: string | null) => void
  itemCounts?: Record<string, number>
  totalItems?: number
}

export function CategoryFilterDropdown({ 
  categories, 
  selectedCategory, 
  onSelectCategory,
  itemCounts = {},
  totalItems = 0
}: CategoryFilterDropdownProps) {
  const sortedCategories = categories.sort((a, b) => a.localeCompare(b))

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button 
          variant="outline" 
          className="min-h-[44px] flex items-center space-x-2"
          data-testid="category-filter"
          aria-label="Filter by category"
        >
          <Filter className="h-4 w-4" />
          <span className="truncate">
            {selectedCategory || 'All Categories'}
          </span>
          {selectedCategory && itemCounts[selectedCategory] && (
            <Badge variant="secondary" className="ml-1 text-xs">
              {itemCounts[selectedCategory]}
            </Badge>
          )}
          <ChevronDown className="h-4 w-4 ml-auto" />
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent 
        align="start" 
        className="w-64 max-h-[60vh] overflow-y-auto"
        sideOffset={4}
      >
        {/* All Categories option */}
        <DropdownMenuItem
          onClick={() => onSelectCategory(null)}
          className="flex items-center justify-between py-3 cursor-pointer"
        >
          <div className="flex items-center space-x-2">
            <span className="font-medium">All Categories</span>
            {!selectedCategory && <Check className="h-4 w-4 text-primary" />}
          </div>
          <Badge variant="outline" className="text-xs">
            {totalItems}
          </Badge>
        </DropdownMenuItem>

        {sortedCategories.length > 0 && <DropdownMenuSeparator />}

        {/* Individual categories */}
        {sortedCategories.map(category => {
          const count = itemCounts[category] || 0
          const isSelected = selectedCategory === category

          return (
            <DropdownMenuItem
              key={category}
              onClick={() => onSelectCategory(isSelected ? null : category)}
              className="flex items-center justify-between py-3 cursor-pointer"
            >
              <div className="flex items-center space-x-2 min-w-0">
                <span className="truncate">{category}</span>
                {isSelected && <Check className="h-4 w-4 text-primary flex-shrink-0" />}
              </div>
              {count > 0 && (
                <Badge variant="outline" className="text-xs flex-shrink-0">
                  {count}
                </Badge>
              )}
            </DropdownMenuItem>
          )
        })}

        {sortedCategories.length === 0 && (
          <DropdownMenuItem disabled className="py-3 text-center text-muted-foreground">
            No categories found
          </DropdownMenuItem>
        )}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

import { useState, useEffect, useMemo, useCallback } from 'react'
import { useAuth } from '@/contexts/AuthContext'
import { Button } from '@/components/ui/button'
import { Card } from '@/components/ui/card'
import { Input } from '@/components/ui/input'
import { Skeleton } from '@/components/ui/skeleton'
import {
  Plus,
  Search,
  Package,
  Filter,
  ChevronDown,
  LayoutGrid,
  TableProperties
} from 'lucide-react'
import { useGearItems, useCreateGear, useUpdateGear, useDeleteGear } from '@/hooks/useGearData'
import { GearTable, type SortField, type SortDirection } from '@/components/gear/GearTable'
import { GearCard } from '@/components/gear/GearCard'
import { ViewModeSelector } from '@/components/gear/ViewModeSelector'
import { WeightUnitSelector } from '@/components/gear/WeightUnitSelector'
import { EditGearForm } from '@/components/gear/EditGearForm'
import { DeleteDialog } from '@/components/gear/DeleteDialog'
import { AddGearFormWrapper } from '@/components/gear/AddGearFormWrapper'
import { AppHeader } from '@/components/navigation/AppHeader'
import { CategoryFilterDropdown } from '@/components/gear/CategoryFilterDropdown'
import type { GearItem, WeightUnit } from '@/types/database'
import { formatWeightWithUnit } from '@/utils/weight'

export type ViewMode = 'compact' | 'default' | 'comfortable'

export function GearCloset() {
  const { user } = useAuth()

  // Use React Query hooks for data fetching and mutations
  const { data: items = [], isLoading: loading } = useGearItems(user?.id)
  const createGearMutation = useCreateGear(user?.id)
  const updateGearMutation = useUpdateGear(user?.id)
  const deleteGearMutation = useDeleteGear(user?.id)

  const [viewMode, setViewMode] = useState<ViewMode>(() => {
    const saved = localStorage.getItem('gearViewMode')
    // Default to comfortable (card) view on mobile for better touch experience
    const isMobile = window.innerWidth < 640
    return (saved as ViewMode) || (isMobile ? 'comfortable' : 'default')
  })
  const [weightUnit, setWeightUnit] = useState<WeightUnit>(() => {
    const saved = localStorage.getItem('gearWeightUnit')
    return (saved as WeightUnit) || 'g'
  })
  const [searchTerm, setSearchTerm] = useState('')
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null)
  const [showAddForm, setShowAddForm] = useState(false)
  const [showMobileFilters, setShowMobileFilters] = useState(false)
  const [editingItem, setEditingItem] = useState<GearItem | null>(null)
  const [deletingItem, setDeletingItem] = useState<GearItem | null>(null)
  const [sortField, setSortField] = useState<SortField>('name')
  const [sortDirection, setSortDirection] = useState<SortDirection>('asc')


  // Save view mode preference
  useEffect(() => {
    localStorage.setItem('gearViewMode', viewMode)
  }, [viewMode])

  // Save weight unit preference
  useEffect(() => {
    localStorage.setItem('gearWeightUnit', weightUnit)
  }, [weightUnit])

  // Filter items based on search and category with memoization
  const filteredItems = useMemo(() => {
    let filtered = items

    if (searchTerm) {
      const searchLower = searchTerm.toLowerCase()
      filtered = filtered.filter(item =>
        item.name.toLowerCase().includes(searchLower) ||
        item.brand?.toLowerCase().includes(searchLower) ||
        item.model?.toLowerCase().includes(searchLower) ||
        item.category.toLowerCase().includes(searchLower) ||
        item.notes?.toLowerCase().includes(searchLower) ||
        item.description?.toLowerCase().includes(searchLower)
      )
    }

    if (selectedCategory) {
      filtered = filtered.filter(item => item.category === selectedCategory)
    }

    return filtered
  }, [items, searchTerm, selectedCategory])

  // Sort filtered items with memoization
  const sortedItems = useMemo(() => {
    const sorted = [...filteredItems].sort((a, b) => {
      let aValue: string | number = a[sortField as keyof GearItem] as string | number
      let bValue: string | number = b[sortField as keyof GearItem] as string | number

      // Handle 'total' which is calculated
      if (sortField === 'total') {
        aValue = a.weight_grams * a.quantity
        bValue = b.weight_grams * b.quantity
      }

      // Handle null/undefined values
      if (aValue == null && bValue == null) return 0
      if (aValue == null) return sortDirection === 'asc' ? 1 : -1
      if (bValue == null) return sortDirection === 'asc' ? -1 : 1

      // Handle string comparison
      if (typeof aValue === 'string' && typeof bValue === 'string') {
        return sortDirection === 'asc'
          ? aValue.localeCompare(bValue)
          : bValue.localeCompare(aValue)
      }

      // Handle number comparison
      if (typeof aValue === 'number' && typeof bValue === 'number') {
        return sortDirection === 'asc'
          ? aValue - bValue
          : bValue - aValue
      }

      // Mixed types - convert to string for comparison
      const aStr = String(aValue)
      const bStr = String(bValue)
      return sortDirection === 'asc'
        ? aStr.localeCompare(bStr)
        : bStr.localeCompare(aStr)
    })

    return sorted
  }, [filteredItems, sortField, sortDirection])

  const handleSort = useCallback((field: SortField) => {
    if (sortField === field) {
      setSortDirection(prev => prev === 'asc' ? 'desc' : 'asc')
    } else {
      setSortField(field)
      setSortDirection('asc')
    }
  }, [sortField])

  // Calculate stats with memoization
  const { totalWeight, baseWeight, categories, categoryCounts } = useMemo(() => {
    const totalWeight = items.reduce((sum, item) => sum + (item.weight_grams * item.quantity), 0)
    const baseWeight = items
      .filter(item => !item.worn && !item.consumable)
      .reduce((sum, item) => sum + (item.weight_grams * item.quantity), 0)
    const categories = Array.from(new Set(items.map(item => item.category)))

    // Calculate category counts for dropdown
    const categoryCounts = items.reduce((acc, item) => {
      acc[item.category] = (acc[item.category] || 0) + 1
      return acc
    }, {} as Record<string, number>)

    return { totalWeight, baseWeight, categories, categoryCounts }
  }, [items])


  const handleAdd = useCallback(async (gear: Omit<GearItem, 'id' | 'user_id' | 'created_at' | 'updated_at'>) => {
    if (!user) return

    try {
      await createGearMutation.mutateAsync(gear)
      setShowAddForm(false)
    } catch (error) {
      // Error is already handled by the mutation's onError
      console.error('Failed to add gear:', error)
    }
  }, [user, createGearMutation])

  const handleUpdate = useCallback(async (id: string, updates: Partial<Omit<GearItem, 'id' | 'user_id' | 'created_at' | 'updated_at'>>) => {
    if (!user) return

    try {
      await updateGearMutation.mutateAsync({ id, updates })
      setEditingItem(null)
    } catch (error) {
      // Error is already handled by the mutation's onError
      console.error('Failed to update gear:', error)
    }
  }, [user, updateGearMutation])

  const handleDelete = useCallback(async (id: string) => {
    if (!user) return

    try {
      await deleteGearMutation.mutateAsync(id)
      setDeletingItem(null)
    } catch (error) {
      // Error is already handled by the mutation's onError
      console.error('Failed to delete gear:', error)
      setDeletingItem(null) // Still close the dialog
    }
  }, [user, deleteGearMutation])

  return (
    <div className="min-h-screen bg-background">
      {/* Unified App Header */}
      <AppHeader
        title="Gear Closet"
        backTo="/dashboard"
        isDashboard={false}
        rightContent={null}
      />

      {/* Filters Bar */}
      <div className="bg-white border-b border-border/40 sticky top-16 z-40">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-3">
          <div className="flex flex-col gap-3">
            {/* Search Bar */}
            <div className="relative">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <Input
                type="text"
                placeholder="Search gear..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pl-10 min-h-[44px]"
              />
            </div>

            {/* Mobile Category & View Controls */}
            <div className="flex gap-2 sm:hidden">
              <Button
                variant="outline"
                className="flex-1 justify-between min-h-[44px]"
                onClick={() => setShowMobileFilters(!showMobileFilters)}
              >
                <span className="flex items-center gap-2">
                  <Filter className="h-4 w-4" />
                  {selectedCategory || 'All Categories'}
                </span>
                <ChevronDown className={`h-4 w-4 transition-transform ${showMobileFilters ? 'rotate-180' : ''}`} />
              </Button>
              <Button
                variant="outline"
                className="justify-center min-h-[44px] min-w-[44px]"
                onClick={() => setViewMode(viewMode === 'comfortable' ? 'default' : 'comfortable')}
              >
                {viewMode === 'comfortable' ? <LayoutGrid className="h-4 w-4" /> : <TableProperties className="h-4 w-4" />}
              </Button>
            </div>

            {/* Desktop Controls Row */}
            <div className="hidden sm:flex gap-2 items-center">
              {/* Category Dropdown */}
              <div className="w-48">
                <CategoryFilterDropdown
                  categories={categories}
                  selectedCategory={selectedCategory}
                  onSelectCategory={setSelectedCategory}
                  itemCounts={categoryCounts}
                  totalItems={items.length}
                />
              </div>

              {/* Stats */}
              <div className="flex-1 text-sm text-muted-foreground px-3">
                {`${items.length} items • ${formatWeightWithUnit(totalWeight, weightUnit)} total • ${formatWeightWithUnit(baseWeight, weightUnit)} base`}
              </div>

              {/* Weight Unit Selector */}
              <WeightUnitSelector value={weightUnit} onChange={setWeightUnit} />

              {/* View Mode Selector */}
              <ViewModeSelector value={viewMode} onChange={setViewMode} />
            </div>
          </div>

          {/* Mobile Category Grid */}
          {showMobileFilters && (
            <div className="mt-3 p-3 bg-muted/50 rounded-lg sm:hidden">
              <div className="grid grid-cols-2 gap-2">
                <Button
                  variant={selectedCategory ? 'outline' : 'default'}
                  size="sm"
                  className="justify-start min-h-[44px]"
                  onClick={() => {
                    setSelectedCategory(null)
                    setShowMobileFilters(false)
                  }}
                >
                  All Categories
                </Button>
                {categories.map(category => (
                  <Button
                    key={category}
                    variant={selectedCategory === category ? 'default' : 'outline'}
                    size="sm"
                    className="justify-start min-h-[44px]"
                    onClick={() => {
                      setSelectedCategory(category === selectedCategory ? null : category)
                      setShowMobileFilters(false)
                    }}
                  >
                    {category}
                  </Button>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
        {loading ? (
          <div className="space-y-4">
            {[...Array(5)].map((_, i) => (
              <Skeleton key={i} className="h-16 w-full" />
            ))}
          </div>
        ) : sortedItems.length === 0 ? (
          <Card className="p-12 text-center">
            <Package className="h-12 w-12 text-muted-foreground mx-auto mb-4" />
            <h3 className="text-lg font-medium mb-2">
              {searchTerm || selectedCategory ? 'No gear found' : 'No gear yet'}
            </h3>
            <p className="text-sm text-muted-foreground mb-4 max-w-sm mx-auto">
              {searchTerm || selectedCategory
                ? 'Try adjusting your filters'
                : 'Get started by adding your first item'
              }
            </p>
            {!searchTerm && !selectedCategory && (
              <Button
                onClick={() => setShowAddForm(true)}
                className="min-h-[44px]"
              >
                <Plus className="h-4 w-4 mr-2" />
                Add First Item
              </Button>
            )}
          </Card>
        ) : viewMode === 'comfortable' ? (
          <div className="grid gap-4 grid-cols-1 sm:grid-cols-2 lg:grid-cols-3">
            {sortedItems.map(item => (
              <GearCard
                key={item.id}
                item={item}
                weightUnit={weightUnit}
                onEdit={() => setEditingItem(item)}
                onDelete={() => setDeletingItem(item)}
              />
            ))}
          </div>
        ) : (
          <GearTable
            items={sortedItems}
            viewMode={viewMode}
            weightUnit={weightUnit}
            onEdit={setEditingItem}
            onDelete={setDeletingItem}
            sortField={sortField}
            sortDirection={sortDirection}
            onSort={handleSort}
          />
        )}

      </main>

      {/* Floating Action Button - Fixed positioning but visually constrained */}
      <div className="fixed bottom-6 right-0 z-50 w-full max-w-7xl mx-auto pointer-events-none">
        <div className="flex justify-end pr-4 sm:pr-6 lg:pr-8 pointer-events-auto">
          <Button
            size="lg"
            className="rounded-full shadow-lg h-14 w-14 p-0 bg-primary hover:bg-primary/90"
            onClick={() => setShowAddForm(true)}
          >
            <Plus className="h-6 w-6" />
          </Button>
        </div>
      </div>

      {/* Add Gear Form Modal */}
      <AddGearFormWrapper
        isOpen={showAddForm}
        onAdd={handleAdd}
        onCancel={() => setShowAddForm(false)}
      />

      {/* Edit Gear Form Modal */}
      {editingItem && (
        <EditGearForm
          item={editingItem}
          onUpdate={handleUpdate}
          onCancel={() => setEditingItem(null)}
        />
      )}

      {/* Delete Confirmation Dialog */}
      {deletingItem && (
        <DeleteDialog
          item={deletingItem}
          onConfirm={() => handleDelete(deletingItem.id)}
          onCancel={() => setDeletingItem(null)}
        />
      )}
    </div>
  )
}

import { useState } from 'react'
import { useAuth } from '@/contexts/AuthContext'
import { AppHeader } from '@/components/navigation/AppHeader'
import { ListsView } from '@/components/lists/ListsView'
import { ListDetailView } from '@/components/lists/ListDetailView'
import { Skeleton } from '@/components/ui/skeleton'
import { Button } from '@/components/ui/button'
import { ArrowLeft, Plus } from 'lucide-react'
import { useLists, useCreateList, useUpdateList, useDeleteList, useDuplicateList } from '@/hooks/useListData'
import { useGearItems } from '@/hooks/useGearData'
import type { List } from '@/types/database'

export function Lists() {
  const { user } = useAuth()
  const [selectedList, setSelectedList] = useState<List | null>(null)
  const [showMobileCreate, setShowMobileCreate] = useState(false)

  // Data fetching
  const { data: lists = [], isLoading: listsLoading } = useLists(user?.id)
  const { data: gearItems = [], isLoading: gearLoading } = useGearItems(user?.id)

  // Mutations
  const createListMutation = useCreateList(user?.id)
  const updateListMutation = useUpdateList(user?.id)
  const deleteListMutation = useDeleteList(user?.id)
  const duplicateListMutation = useDuplicateList(user?.id)

  const handleCreateList = async (data: Omit<List, 'id' | 'user_id' | 'created_at' | 'updated_at'>) => {
    await createListMutation.mutateAsync(data)
  }

  const handleEditList = async (id: string, updates: Partial<Omit<List, 'id' | 'user_id' | 'created_at' | 'updated_at'>>) => {
    await updateListMutation.mutateAsync({ id, updates })
  }

  const handleDeleteList = async (id: string) => {
    await deleteListMutation.mutateAsync(id)
    // If we're viewing the deleted list, go back to list view
    if (selectedList?.id === id) {
      setSelectedList(null)
    }
  }

  const handleDuplicateList = async (listId: string, newName: string) => {
    await duplicateListMutation.mutateAsync({ listId, newName })
  }

  const handleViewList = (list: List) => {
    setSelectedList(list)
  }

  const handleBackToLists = () => {
    setSelectedList(null)
  }

  const isLoading = listsLoading || gearLoading

  if (selectedList) {
    return (
      <div className="min-h-screen bg-background">
        <AppHeader />
        <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6 sm:py-10">
          <div className="mb-6">
            <Button
              variant="ghost"
              onClick={handleBackToLists}
              className="mb-4"
            >
              <ArrowLeft className="w-4 h-4 mr-2" />
              Back to Lists
            </Button>
          </div>

          <ListDetailView
            list={selectedList}
            gearItems={gearItems}
            onEditList={handleEditList}
            onDeleteList={handleDeleteList}
            onBackToLists={handleBackToLists}
          />
        </main>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-background">
      <AppHeader />

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6 sm:py-10">
        {isLoading ? (
          <div className="space-y-6">
            <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
              <div>
                <Skeleton className="h-8 w-48 mb-2" />
                <Skeleton className="h-5 w-64" />
              </div>
              <Skeleton className="h-10 w-32" />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {Array.from({ length: 6 }).map((_, i) => (
                <div key={i} className="border rounded-lg p-6 space-y-4">
                  <Skeleton className="h-32 w-full" />
                  <Skeleton className="h-6 w-3/4" />
                  <Skeleton className="h-4 w-1/2" />
                  <div className="grid grid-cols-3 gap-4">
                    <Skeleton className="h-12 w-full" />
                    <Skeleton className="h-12 w-full" />
                    <Skeleton className="h-12 w-full" />
                  </div>
                  <div className="flex gap-2">
                    <Skeleton className="h-9 flex-1" />
                    <Skeleton className="h-9 w-9" />
                    <Skeleton className="h-9 w-9" />
                    <Skeleton className="h-9 w-9" />
                  </div>
                </div>
              ))}
            </div>
          </div>
        ) : (
          <ListsView
            lists={lists}
            gearItems={gearItems}
            onCreateList={handleCreateList}
            onEditList={handleEditList}
            onDeleteList={handleDeleteList}
            onDuplicateList={handleDuplicateList}
            onViewList={handleViewList}
            loading={createListMutation.isPending || updateListMutation.isPending || deleteListMutation.isPending}
          />
        )}

        {/* Mobile Floating Action Button */}
        <div className="fixed bottom-20 right-6 md:hidden z-50">
          <Button
            size="lg"
            className="rounded-full shadow-lg w-14 h-14 p-0"
            onClick={() => setShowMobileCreate(!showMobileCreate)}
            disabled={isLoading}
          >
            {showMobileCreate ? (
              <ArrowLeft className="h-6 w-6" />
            ) : (
              <Plus className="h-6 w-6" />
            )}
          </Button>
        </div>
      </main>
    </div>
  )
}

