import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { 
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
  DropdownMenuSeparator,
} from '@/components/ui/dropdown-menu'
import { Filter, ChevronDown, Check } from 'lucide-react'

interface FilterOption {
  value: string
  label: string
  count?: number
}

interface FilterDropdownProps {
  options: FilterOption[]
  selectedValue: string | null
  onSelectValue: (value: string | null) => void
  placeholder?: string
  allItemsLabel?: string
  totalItems?: number
  className?: string
  'data-testid'?: string
  'aria-label'?: string
}

export function FilterDropdown({ 
  options, 
  selectedValue, 
  onSelectValue,
  placeholder = 'All Items',
  allItemsLabel = 'All Items',
  totalItems = 0,
  className = '',
  'data-testid': testId,
  'aria-label': ariaLabel,
}: FilterDropdownProps) {
  const sortedOptions = options.sort((a, b) => a.label.localeCompare(b.label))
  const selectedOption = options.find(opt => opt.value === selectedValue)

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button 
          variant="outline" 
          className={`min-h-[44px] flex items-center space-x-2 ${className}`}
          data-testid={testId}
          aria-label={ariaLabel}
        >
          <Filter className="h-4 w-4" />
          <span className="truncate">
            {selectedOption?.label || placeholder}
          </span>
          {selectedOption?.count !== undefined && (
            <Badge variant="secondary" className="ml-1 text-xs">
              {selectedOption.count}
            </Badge>
          )}
          <ChevronDown className="h-4 w-4 ml-auto" />
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent 
        align="start" 
        className="w-64 max-h-[60vh] overflow-y-auto"
        sideOffset={4}
      >
        {/* All Items option */}
        <DropdownMenuItem
          onClick={() => onSelectValue(null)}
          className="flex items-center justify-between py-3 cursor-pointer"
        >
          <div className="flex items-center space-x-2">
            <span className="font-medium">{allItemsLabel}</span>
            {!selectedValue && <Check className="h-4 w-4 text-primary" />}
          </div>
          <Badge variant="outline" className="text-xs">
            {totalItems}
          </Badge>
        </DropdownMenuItem>

        {sortedOptions.length > 0 && <DropdownMenuSeparator />}

        {/* Individual options */}
        {sortedOptions.map(option => {
          const isSelected = selectedValue === option.value

          return (
            <DropdownMenuItem
              key={option.value}
              onClick={() => onSelectValue(isSelected ? null : option.value)}
              className="flex items-center justify-between py-3 cursor-pointer"
            >
              <div className="flex items-center space-x-2 min-w-0">
                <span className="truncate">{option.label}</span>
                {isSelected && <Check className="h-4 w-4 text-primary flex-shrink-0" />}
              </div>
              {option.count !== undefined && option.count > 0 && (
                <Badge variant="outline" className="text-xs flex-shrink-0">
                  {option.count}
                </Badge>
              )}
            </DropdownMenuItem>
          )
        })}

        {sortedOptions.length === 0 && (
          <DropdownMenuItem disabled className="py-3 text-center text-muted-foreground">
            No options found
          </DropdownMenuItem>
        )}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

