import { useMemo } from 'react'

interface FilterConfig<T> {
  searchFields: (keyof T)[]  // Fields to search in
  primaryFilterField?: keyof T  // Field for primary filter (e.g., 'category')
}

interface UseFilteredItemsProps<T> {
  items: T[]
  searchTerm: string
  primaryFilterValue: string | null
  config: FilterConfig<T>
}

export function useFilteredItems<T>({
  items,
  searchTerm,
  primaryFilterValue,
  config
}: UseFilteredItemsProps<T>) {
  const filteredItems = useMemo(() => {
    let filtered = items

    // Apply search filter
    if (searchTerm) {
      const searchLower = searchTerm.toLowerCase()
      filtered = filtered.filter(item => 
        config.searchFields.some(field => {
          const value = item[field]
          return value && 
            typeof value === 'string' && 
            value.toLowerCase().includes(searchLower)
        })
      )
    }

    // Apply primary filter
    if (primaryFilterValue && config.primaryFilterField) {
      filtered = filtered.filter(item => 
        item[config.primaryFilterField!] === primaryFilterValue
      )
    }

    return filtered
  }, [items, searchTerm, primaryFilterValue, config])

  // Calculate filter options for primary filter
  const primaryFilterOptions = useMemo(() => {
    if (!config.primaryFilterField) return []

    const fieldCounts: Record<string, number> = {}

    items.forEach(item => {
      const value = item[config.primaryFilterField!]
      if (value && typeof value === 'string') {
        fieldCounts[value] = (fieldCounts[value] || 0) + 1
      }
    })

    return Object.entries(fieldCounts).map(([value, count]) => ({
      value,
      label: value,
      count
    }))
  }, [items, config.primaryFilterField])

  return {
    filteredItems,
    primaryFilterOptions,
    totalItems: items.length
  }
}

