import { useGearItems, useCreateGear, useUpdateGear, useDeleteGear } from '@/hooks/useGearData'
import { GearTable, type SortField, type SortDirection } from '@/components/gear/GearTable'
import { GearCard } from '@/components/gear/GearCard'
import { ViewModeSelector } from '@/components/gear/ViewModeSelector'
import { WeightUnitSelector } from '@/components/gear/WeightUnitSelector'
import { EditGearForm } from '@/components/gear/EditGearForm'
import { DeleteDialog } from '@/components/gear/DeleteDialog'
import { AddGearFormWrapper } from '@/components/gear/AddGearFormWrapper'
import { AppHeader } from '@/components/navigation/AppHeader'
import { ListDisplayHeader } from '@/components/shared/ListDisplayHeader'
import { useFilteredItems } from '@/hooks/shared/useFilteredItems'
import type { GearItem, WeightUnit } from '@/types/database'
import { formatWeightWithUnit } from '@/utils/weight'

export type ViewMode = 'compact' | 'default' | 'comfortable'

export function GearCloset() {
  const { user } = useAuth()

  // Use React Query hooks for data fetching and mutations
  const { data: items = [], isLoading: loading } = useGearItems(user?.id)
  const createGearMutation = useCreateGear(user?.id)
  const updateGearMutation = useUpdateGear(user?.id)
  const deleteGearMutation = useDeleteGear(user?.id)

  const [viewMode, setViewMode] = useState<ViewMode>(() => {
    const saved = localStorage.getItem('gearViewMode')
    // Default to comfortable (card) view on mobile for better touch experience
    const isMobile = window.innerWidth < 640
    return (saved as ViewMode) || (isMobile ? 'comfortable' : 'default')
  })
  const [weightUnit, setWeightUnit] = useState<WeightUnit>(() => {
    const saved = localStorage.getItem('gearWeightUnit')
    return (saved as WeightUnit) || 'g'
  })
  const [searchTerm, setSearchTerm] = useState('')
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null)
  const [showAddForm, setShowAddForm] = useState(false)
  const [editingItem, setEditingItem] = useState<GearItem | null>(null)
  const [deletingItem, setDeletingItem] = useState<GearItem | null>(null)
  const [sortField, setSortField] = useState<SortField>('name')
  const [sortDirection, setSortDirection] = useState<SortDirection>('asc')


  // Save view mode preference
  useEffect(() => {
    localStorage.setItem('gearViewMode', viewMode)
  }, [viewMode])

  // Save weight unit preference
  useEffect(() => {
    localStorage.setItem('gearWeightUnit', weightUnit)
  }, [weightUnit])

  // Filter items based on search and category with memoization
  const filteredItems = useMemo(() => {
    let filtered = items

    if (searchTerm) {
      const searchLower = searchTerm.toLowerCase()
      filtered = filtered.filter(item =>
        item.name.toLowerCase().includes(searchLower) ||
        item.brand?.toLowerCase().includes(searchLower) ||
        item.model?.toLowerCase().includes(searchLower) ||
        item.category.toLowerCase().includes(searchLower) ||
        item.notes?.toLowerCase().includes(searchLower) ||
        item.description?.toLowerCase().includes(searchLower)
      )
    }

    if (selectedCategory) {
      filtered = filtered.filter(item => item.category === selectedCategory)
    }

    return filtered
  }, [items, searchTerm, selectedCategory])

  // Sort filtered items with memoization
  const sortedItems = useMemo(() => {
    const sorted = [...filteredItems].sort((a, b) => {
      let aValue: string | number = a[sortField as keyof GearItem] as string | number
      let bValue: string | number = b[sortField as keyof GearItem] as string | number

      // Handle 'total' which is calculated
      if (sortField === 'total') {
        aValue = a.weight_grams * a.quantity
        bValue = b.weight_grams * b.quantity
      }

      // Handle null/undefined values
      if (aValue == null && bValue == null) return 0
      if (aValue == null) return sortDirection === 'asc' ? 1 : -1
      if (bValue == null) return sortDirection === 'asc' ? -1 : 1

      // Handle string comparison
      if (typeof aValue === 'string' && typeof bValue === 'string') {
        return sortDirection === 'asc'
          ? aValue.localeCompare(bValue)
          : bValue.localeCompare(aValue)
      }

      // Handle number comparison
      if (typeof aValue === 'number' && typeof bValue === 'number') {
        return sortDirection === 'asc'
          ? aValue - bValue
          : bValue - aValue
      }

      // Mixed types - convert to string for comparison
      const aStr = String(aValue)
      const bStr = String(bValue)
      return sortDirection === 'asc'
        ? aStr.localeCompare(bStr)
        : bStr.localeCompare(aStr)
    })

    return sorted
  }, [filteredItems, sortField, sortDirection])

  const handleSort = useCallback((field: SortField) => {
    if (sortField === field) {
      setSortDirection(prev => prev === 'asc' ? 'desc' : 'asc')
    } else {
      setSortField(field)
      setSortDirection('asc')
    }
  }, [sortField])

  // Calculate stats with memoization
  const { totalWeight, baseWeight, categories, categoryCounts } = useMemo(() => {
    const totalWeight = items.reduce((sum, item) => sum + (item.weight_grams * item.quantity), 0)
    const baseWeight = items
      .filter(item => !item.worn && !item.consumable)
      .reduce((sum, item) => sum + (item.weight_grams * item.quantity), 0)
    const categories = Array.from(new Set(items.map(item => item.category)))

    // Calculate category counts for dropdown
    const categoryCounts = items.reduce((acc, item) => {
      acc[item.category] = (acc[item.category] || 0) + 1
      return acc
    }, {} as Record<string, number>)

    return { totalWeight, baseWeight, categories, categoryCounts }
  }, [items])


  const handleAdd = useCallback(async (gear: Omit<GearItem, 'id' | 'user_id' | 'created_at' | 'updated_at'>) => {
    if (!user) return

    try {
      await createGearMutation.mutateAsync(gear)
      setShowAddForm(false)
    } catch (error) {
      // Error is already handled by the mutation's onError
      console.error('Failed to add gear:', error)
    }
  }, [user, createGearMutation])

  const handleUpdate = useCallback(async (id: string, updates: Partial<Omit<GearItem, 'id' | 'user_id' | 'created_at' | 'updated_at'>>) => {
    if (!user) return

    try {
      await updateGearMutation.mutateAsync({ id, updates })
      setEditingItem(null)
    } catch (error) {
      // Error is already handled by the mutation's onError
      console.error('Failed to update gear:', error)
    }
  }, [user, updateGearMutation])

  const handleDelete = useCallback(async (id: string) => {
    if (!user) return

    try {
      await deleteGearMutation.mutateAsync(id)
      setDeletingItem(null)
    } catch (error) {
      // Error is already handled by the mutation's onError
      console.error('Failed to delete gear:', error)
      setDeletingItem(null) // Still close the dialog
    }
  }, [user, deleteGearMutation])

  return (
    <div className="min-h-screen bg-background">
      {/* Unified App Header */}
      <AppHeader
        title="Gear Closet"
        backTo="/dashboard"
        isDashboard={false}
        rightContent={null}
      />

      {/* List Display Header */}
      <ListDisplayHeader
        searchTerm={searchTerm}
        onSearchChange={setSearchTerm}
        searchPlaceholder="Search gear..."
        primaryFilter={{
          options: categories.map(category => ({
            value: category,
            label: category,
            count: categoryCounts[category]
          })),
          selectedValue: selectedCategory,
          onSelectValue: setSelectedCategory,
          placeholder: 'All Categories',
          allItemsLabel: 'All Categories',
          totalItems: items.length
        }}
        stats={{
          itemCount: items.length,
          itemLabel: 'items',
          additionalInfo: ` • ${formatWeightWithUnit(totalWeight, weightUnit)} total • ${formatWeightWithUnit(baseWeight, weightUnit)} base`
        }}
        secondaryControls={
          <>
            <Button
              variant="outline"
              className="justify-center min-h-[44px] min-w-[44px] sm:hidden"
              onClick={() => setViewMode(viewMode === 'comfortable' ? 'default' : 'comfortable')}
            >
              {viewMode === 'comfortable' ? <LayoutGrid className="h-4 w-4" /> : <TableProperties className="h-4 w-4" />}
            </Button>
            <div className="hidden sm:flex gap-2">
              <WeightUnitSelector value={weightUnit} onChange={setWeightUnit} />
              <ViewModeSelector value={viewMode} onChange={setViewMode} />
            </div>
          </>
        }
        mobileFilterOptions={categories.map(category => ({
          value: category,
          label: category,
          count: categoryCounts[category]
        }))}
      />

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
        {loading ? (
          <div className="space-y-4">
            {[...Array(5)].map((_, i) => (
              <Skeleton key={i} className="h-16 w-full" />
            ))}
          </div>
        ) : sortedItems.length === 0 ? (
          <Card className="p-12 text-center">
            <Package className="h-12 w-12 text-muted-foreground mx-auto mb-4" />
            <h3 className="text-lg font-medium mb-2">
              {searchTerm || selectedCategory ? 'No gear found' : 'No gear yet'}
            </h3>
            <p className="text-sm text-muted-foreground mb-4 max-w-sm mx-auto">
              {searchTerm || selectedCategory
                ? 'Try adjusting your filters'
                : 'Get started by adding your first item'
              }
            </p>
            {!searchTerm && !selectedCategory && (
              <Button
                onClick={() => setShowAddForm(true)}
                className="min-h-[44px]"
              >
                <Plus className="h-4 w-4 mr-2" />
                Add First Item
              </Button>
            )}
          </Card>
        ) : viewMode === 'comfortable' ? (
          <div className="grid gap-4 grid-cols-1 sm:grid-cols-2 lg:grid-cols-3">
            {sortedItems.map(item => (
              <GearCard
                key={item.id}
                item={item}
                weightUnit={weightUnit}
                onEdit={() => setEditingItem(item)}
                onDelete={() => setDeletingItem(item)}
              />
            ))}
          </div>
        ) : (
          <GearTable
            items={sortedItems}
            viewMode={viewMode}
            weightUnit={weightUnit}
            onEdit={setEditingItem}
            onDelete={setDeletingItem}
            sortField={sortField}
            sortDirection={sortDirection}
            onSort={handleSort}
          />
        )}

      </main>

      {/* Floating Action Button - Fixed positioning but visually constrained */}
      <div className="fixed bottom-6 right-0 z-50 w-full max-w-7xl mx-auto pointer-events-none">
        <div className="flex justify-end pr-4 sm:pr-6 lg:pr-8 pointer-events-auto">
          <Button
            size="lg"
            className="rounded-full shadow-lg h-14 w-14 p-0 bg-primary hover:bg-primary/90"
            onClick={() => setShowAddForm(true)}
          >
            <Plus className="h-6 w-6" />
          </Button>
        </div>
      </div>

      {/* Add Gear Form Modal */}
      <AddGearFormWrapper
        isOpen={showAddForm}
        onAdd={handleAdd}
        onCancel={() => setShowAddForm(false)}
      />

      {/* Edit Gear Form Modal */}
      {editingItem && (
        <EditGearForm
          item={editingItem}
          onUpdate={handleUpdate}
          onCancel={() => setEditingItem(null)}
        />
      )}

      {/* Delete Confirmation Dialog */}
      {deletingItem && (
        <DeleteDialog
          item={deletingItem}
          onConfirm={() => handleDelete(deletingItem.id)}
          onCancel={() => setDeletingItem(null)}
        />
      )}
    </div>
  )
}

