import { useState, useMemo } from 'react'
import { ListCard } from './ListCard'
import { CreateListFormWrapper } from './CreateListFormWrapper'
import { EditListFormWrapper } from './EditListFormWrapper'
import { DeleteListDialog } from './DeleteListDialog'
import { ListDisplayHeader } from '@/components/shared/ListDisplayHeader'
import { Button } from '@/components/ui/button'
import { Plus, Package } from 'lucide-react'
import type { List, GearItem, WeightUnit } from '@/types/database'

interface ListsViewProps {
  lists: List[]
  gearItems: GearItem[] // All gear items for weight calculations
  weightUnit?: WeightUnit
  onCreateList: (data: Omit<List, 'id' | 'user_id' | 'created_at' | 'updated_at'>) => void
  onEditList: (id: string, updates: Partial<Omit<List, 'id' | 'user_id' | 'created_at' | 'updated_at'>>) => void
  onDeleteList: (id: string) => void
  onDuplicateList: (listId: string, newName: string) => void
  onViewList: (list: List) => void
  loading?: boolean
}

export function ListsView({
  lists,
  gearItems,
  weightUnit = 'g',
  onCreateList,
  onEditList,
  onDeleteList,
  onDuplicateList,
  onViewList,
  loading = false
}: ListsViewProps) {
  const [searchTerm, setSearchTerm] = useState('')
  const [showCreateForm, setShowCreateForm] = useState(false)
  const [editingList, setEditingList] = useState<List | null>(null)
  const [deletingList, setDeletingList] = useState<List | null>(null)

  const handleCreateList = async (data: Omit<List, 'id' | 'user_id' | 'created_at' | 'updated_at'>) => {
    await onCreateList(data)
    setShowCreateForm(false)
  }

  const handleEditList = async (id: string, updates: Partial<Omit<List, 'id' | 'user_id' | 'created_at' | 'updated_at'>>) => {
    await onEditList(id, updates)
    setEditingList(null)
  }

  const handleDeleteList = async (list: List) => {
    await onDeleteList(list.id)
    setDeletingList(null)
  }

  const handleDuplicateList = async (list: List) => {
    const newName = `${list.name} (Copy)`
    await onDuplicateList(list.id, newName)
  }

  // Filter lists based on search term
  const filteredLists = useMemo(() => {
    if (!searchTerm) return lists

    const searchLower = searchTerm.toLowerCase()
    return lists.filter(list =>
      list.name.toLowerCase().includes(searchLower) ||
      list.description?.toLowerCase().includes(searchLower) ||
      list.activity_type?.toLowerCase().includes(searchLower)
    )
  }, [lists, searchTerm])

  if (lists.length === 0 && !loading) {
    return (
      <>
        <div className="text-center py-12">
          <div className="mx-auto w-24 h-24 bg-muted rounded-full flex items-center justify-center mb-6">
            <Package className="w-12 h-12 text-muted-foreground/50" />
          </div>
          <h3 className="text-xl font-semibold mb-2">No lists yet</h3>
          <p className="text-muted-foreground mb-6 max-w-sm mx-auto">
            Create your first list to start organizing gear for different adventures and trips.
          </p>
          <Button
            onClick={() => setShowCreateForm(true)}
            className="bg-primary hover:bg-primary/90"
          >
            <Plus className="w-4 h-4 mr-2" />
            Create Your First List
          </Button>
        </div>

        {/* Create Form */}
        {showCreateForm && (
          <CreateListFormWrapper
            isOpen={showCreateForm}
            onCreate={handleCreateList}
            onCancel={() => setShowCreateForm(false)}
          />
        )}
      </>
    )
  }

  return (
    <>
      <div className="space-y-6">
        {/* Header */}
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
          <div>
            <h2 className="text-2xl font-bold">Your Lists</h2>
          </div>
          <Button
            onClick={() => setShowCreateForm(true)}
            className="bg-primary hover:bg-primary/90"
            disabled={loading}
          >
            <Plus className="w-4 h-4 mr-2" />
            Create List
          </Button>
        </div>

        {/* List Display Header */}
        <ListDisplayHeader
          searchTerm={searchTerm}
          onSearchChange={setSearchTerm}
          searchPlaceholder="Search lists..."
          stats={{
            itemCount: filteredLists.length,
            itemLabel: filteredLists.length !== 1 ? 'lists' : 'list',
            additionalInfo: ' • Organize gear for different adventures'
          }}
        />

        {/* Lists Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredLists.length === 0 && searchTerm ? (
            <div className="col-span-full text-center py-12">
              <Package className="w-12 h-12 text-muted-foreground mx-auto mb-4" />
              <h3 className="text-lg font-medium mb-2">No lists found</h3>
              <p className="text-muted-foreground">
                Try adjusting your search term
              </p>
            </div>
          ) : (
            filteredLists.map((list) => (
            <ListCard
              key={list.id}
              list={list}
              gearItems={gearItems}
              weightUnit={weightUnit}
              onView={onViewList}
              onEdit={setEditingList}
              onDelete={setDeletingList}
              onDuplicate={handleDuplicateList}
            />
          ))}
        </div>
      </div>

      {/* Create Form */}
      {showCreateForm && (
        <CreateListFormWrapper
          isOpen={showCreateForm}
          onCreate={handleCreateList}
          onCancel={() => setShowCreateForm(false)}
        />
      )}

      {/* Edit Form */}
      {editingList && (
        <EditListFormWrapper
          isOpen={!!editingList}
          list={editingList}
          onEdit={handleEditList}
          onCancel={() => setEditingList(null)}
        />
      )}

      {/* Delete Dialog */}
      {deletingList && (
        <DeleteListDialog
          list={deletingList}
          onConfirm={() => handleDeleteList(deletingList)}
          onCancel={() => setDeletingList(null)}
        />
      )}
    </>
  )
}

import { useState } from 'react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Search, Filter, ChevronDown, LayoutGrid, TableProperties } from 'lucide-react'
import { FilterDropdown } from './FilterDropdown'

interface FilterOption {
  value: string
  label: string
  count?: number
}

interface ListDisplayHeaderProps {
  // Search
  searchTerm: string
  onSearchChange: (term: string) => void
  searchPlaceholder?: string

  // Primary Filter (optional)
  primaryFilter?: {
    options: FilterOption[]
    selectedValue: string | null
    onSelectValue: (value: string | null) => void
    placeholder?: string
    allItemsLabel?: string
    totalItems?: number
  }

  // Stats (mandatory)
  stats: {
    itemCount: number
    itemLabel: string  // e.g., "items", "lists" 
    additionalInfo?: string  // e.g., "• 2.5kg total • 1.8kg base"
  }

  // Secondary controls (optional)
  secondaryControls?: React.ReactNode

  // Mobile filter options (if primaryFilter provided)
  mobileFilterOptions?: FilterOption[]

  // Styling
  className?: string
}

export function ListDisplayHeader({
  searchTerm,
  onSearchChange,
  searchPlaceholder = "Search...",
  primaryFilter,
  stats,
  secondaryControls,
  mobileFilterOptions,
  className = ""
}: ListDisplayHeaderProps) {
  const [showMobileFilters, setShowMobileFilters] = useState(false)

  const selectedFilterOption = primaryFilter?.options.find(
    opt => opt.value === primaryFilter.selectedValue
  )

  return (
    <div className={`bg-white border-b border-border/40 sticky top-16 z-40 ${className}`}>
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-3">
        <div className="flex flex-col gap-3">
          {/* Search Bar */}
          <div className="relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-muted-foreground" />
            <Input
              type="text"
              placeholder={searchPlaceholder}
              value={searchTerm}
              onChange={(e) => onSearchChange(e.target.value)}
              className="pl-10 min-h-[44px]"
            />
          </div>

          {/* Mobile Filter & Controls */}
          {primaryFilter && (
            <div className="flex gap-2 sm:hidden">
              <Button
                variant="outline"
                className="flex-1 justify-between min-h-[44px]"
                onClick={() => setShowMobileFilters(!showMobileFilters)}
              >
                <span className="flex items-center gap-2">
                  <Filter className="h-4 w-4" />
                  {selectedFilterOption?.label || primaryFilter.placeholder || 'All Items'}
                </span>
                <ChevronDown className={`h-4 w-4 transition-transform ${showMobileFilters ? 'rotate-180' : ''}`} />
              </Button>
              {secondaryControls && (
                <div className="flex gap-2">
                  {secondaryControls}
                </div>
              )}
            </div>
          )}

          {/* Desktop Controls Row */}
          <div className="hidden sm:flex gap-2 items-center">
            {/* Primary Filter */}
            {primaryFilter && (
              <div className="w-48">
                <FilterDropdown
                  options={primaryFilter.options}
                  selectedValue={primaryFilter.selectedValue}
                  onSelectValue={primaryFilter.onSelectValue}
                  placeholder={primaryFilter.placeholder}
                  allItemsLabel={primaryFilter.allItemsLabel}
                  totalItems={primaryFilter.totalItems}
                />
              </div>
            )}

            {/* Stats */}
            <div className="flex-1 text-sm text-muted-foreground px-3">
              {`${stats.itemCount} ${stats.itemLabel}${stats.additionalInfo || ''}`}
            </div>

            {/* Secondary Controls */}
            {secondaryControls && (
              <div className="flex gap-2 items-center">
                {secondaryControls}
              </div>
            )}
          </div>
        </div>

        {/* Mobile Filter Grid */}
        {primaryFilter && showMobileFilters && mobileFilterOptions && (
          <div className="mt-3 p-3 bg-muted/50 rounded-lg sm:hidden">
            <div className="grid grid-cols-2 gap-2">
              <Button
                variant={primaryFilter.selectedValue ? 'outline' : 'default'}
                size="sm"
                className="justify-start min-h-[44px]"
                onClick={() => {
                  primaryFilter.onSelectValue(null)
                  setShowMobileFilters(false)
                }}
              >
                {primaryFilter.allItemsLabel || 'All Items'}
              </Button>
              {mobileFilterOptions.map(option => (
                <Button
                  key={option.value}
                  variant={primaryFilter.selectedValue === option.value ? 'default' : 'outline'}
                  size="sm"
                  className="justify-start min-h-[44px]"
                  onClick={() => {
                    primaryFilter.onSelectValue(option.value === primaryFilter.selectedValue ? null : option.value)
                    setShowMobileFilters(false)
                  }}
                >
                  {option.label}
                </Button>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

