                />
              </div>
            )}

            {/* Stats */}
            <div className="flex-1 text-sm text-muted-foreground px-3">
              {`${stats.itemCount} ${stats.itemLabel}${stats.additionalInfo || ''}`}
            </div>

            {/* Secondary Controls */}
            {secondaryControls && (
              <div className="flex gap-2 items-center">
                {secondaryControls}
              </div>
            )}
          </div>
        </div>

        {/* Mobile Filter Grid */}
        {primaryFilter && showMobileFilters && mobileFilterOptions && (
          <div className="mt-3 p-3 bg-muted/50 rounded-lg sm:hidden">
            <div className="grid grid-cols-2 gap-2">
              <Button
                variant={primaryFilter.selectedValue ? 'outline' : 'default'}
                size="sm"
                className="justify-start min-h-[44px]"
