    try {
      await createGearMutation.mutateAsync(gear)
      setShowAddForm(false)
    } catch (error) {
      // Error is already handled by the mutation's onError
      console.error('Failed to add gear:', error)
    }
  }, [user, createGearMutation])

  const handleUpdate = useCallback(async (id: string, updates: Partial<Omit<GearItem, 'id' | 'user_id' | 'created_at' | 'updated_at'>>) => {
    if (!user) return

    try {
      await updateGearMutation.mutateAsync({ id, updates })
      setEditingItem(null)
    } catch (error) {
      // Error is already handled by the mutation's onError
      console.error('Failed to update gear:', error)
    }
  }, [user, updateGearMutation])

  const handleDelete = useCallback(async (id: string) => {
    if (!user) return

    try {
      await deleteGearMutation.mutateAsync(id)
      setDeletingItem(null)
    } catch (error) {
      // Error is already handled by the mutation's onError
      console.error('Failed to delete gear:', error)
      setDeletingItem(null) // Still close the dialog
    }
  }, [user, deleteGearMutation])

  return (
    <div className="min-h-screen bg-background">
      {/* Unified App Header */}
      <AppHeader
        title="Gear Closet"
        backTo="/dashboard"
        isDashboard={false}
        rightContent={null}
      />

      {/* List Display Header */}
      <ListDisplayHeader
        searchTerm={searchTerm}
        onSearchChange={setSearchTerm}
        searchPlaceholder="Search gear..."
        primaryFilter={{
          options: categories.map(category => ({
            value: category,
            label: category,
            count: categoryCounts[category]
          })),
          selectedValue: selectedCategory,
          onSelectValue: setSelectedCategory,
          placeholder: 'All Categories',
          allItemsLabel: 'All Categories',
          totalItems: items.length
        }}
        stats={{
          itemCount: items.length,
          itemLabel: 'items',
          additionalInfo: ` • ${formatWeightWithUnit(totalWeight, weightUnit)} total • ${formatWeightWithUnit(baseWeight, weightUnit)} base`
        }}
        secondaryControls={
          <>
            <Button
              variant="outline"
              className="justify-center min-h-[44px] min-w-[44px] sm:hidden"
              onClick={() => setViewMode(viewMode === 'comfortable' ? 'default' : 'comfortable')}
            >
              {viewMode === 'comfortable' ? <LayoutGrid className="h-4 w-4" /> : <TableProperties className="h-4 w-4" />}
            </Button>
            <div className="hidden sm:flex gap-2">
              <WeightUnitSelector value={weightUnit} onChange={setWeightUnit} />
              <ViewModeSelector value={viewMode} onChange={setViewMode} />
            </div>
          </>
        }
        mobileFilterOptions={categories.map(category => ({
          value: category,
          label: category,
          count: categoryCounts[category]
        }))}
      />

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
        {loading ? (
          <div className="space-y-4">
            {[...Array(5)].map((_, i) => (
              <Skeleton key={i} className="h-16 w-full" />
            ))}
          </div>
        ) : sortedItems.length === 0 ? (
          <Card className="p-12 text-center">
            <Package className="h-12 w-12 text-muted-foreground mx-auto mb-4" />
            <h3 className="text-lg font-medium mb-2">
              {searchTerm || selectedCategory ? 'No gear found' : 'No gear yet'}
            </h3>
            <p className="text-sm text-muted-foreground mb-4 max-w-sm mx-auto">
              {searchTerm || selectedCategory
                ? 'Try adjusting your filters'
                : 'Get started by adding your first item'
              }
            </p>
            {!searchTerm && !selectedCategory && (
              <Button
                onClick={() => setShowAddForm(true)}
                className="min-h-[44px]"
              >
                <Plus className="h-4 w-4 mr-2" />
                Add First Item
              </Button>
            )}
          </Card>
        ) : viewMode === 'comfortable' ? (
          <div className="grid gap-4 grid-cols-1 sm:grid-cols-2 lg:grid-cols-3">
            {sortedItems.map(item => (
              <GearCard
                key={item.id}
                item={item}
                weightUnit={weightUnit}
                onEdit={() => setEditingItem(item)}
                onDelete={() => setDeletingItem(item)}
              />
            ))}
          </div>
        ) : (
          <GearTable
            items={sortedItems}
            viewMode={viewMode}
            weightUnit={weightUnit}
            onEdit={setEditingItem}
            onDelete={setDeletingItem}
            sortField={sortField}
            sortDirection={sortDirection}
            onSort={handleSort}
          />
        )}

      </main>

      {/* Floating Action Button - Fixed positioning but visually constrained */}
      <div className="fixed bottom-6 right-0 z-50 w-full max-w-7xl mx-auto pointer-events-none">
        <div className="flex justify-end pr-4 sm:pr-6 lg:pr-8 pointer-events-auto">
          <Button
            size="lg"
            className="rounded-full shadow-lg h-14 w-14 p-0 bg-primary hover:bg-primary/90"
            onClick={() => setShowAddForm(true)}
          >
            <Plus className="h-6 w-6" />
          </Button>
        </div>
      </div>

      {/* Add Gear Form Modal */}
      <AddGearFormWrapper
        isOpen={showAddForm}
        onAdd={handleAdd}
        onCancel={() => setShowAddForm(false)}
      />

      {/* Edit Gear Form Modal */}
      {editingItem && (
        <EditGearForm
          item={editingItem}
          onUpdate={handleUpdate}
          onCancel={() => setEditingItem(null)}
        />
      )}

      {/* Delete Confirmation Dialog */}
      {deletingItem && (
        <DeleteDialog
          item={deletingItem}
          onConfirm={() => handleDelete(deletingItem.id)}
          onCancel={() => setDeletingItem(null)}
        />
      )}
    </div>
  )
}

import { useState } from 'react'
import { useAuth } from '@/contexts/AuthContext'
import { AppHeader } from '@/components/navigation/AppHeader'
import { ListsView } from '@/components/lists/ListsView'
import { ListDetailView } from '@/components/lists/ListDetailView'
import { Skeleton } from '@/components/ui/skeleton'
import { Button } from '@/components/ui/button'
import { ArrowLeft, Plus } from 'lucide-react'
import { useLists, useCreateList, useUpdateList, useDeleteList, useDuplicateList } from '@/hooks/useListData'
import { useGearItems } from '@/hooks/useGearData'
import type { List } from '@/types/database'

export function Lists() {
  const { user } = useAuth()
  const [selectedList, setSelectedList] = useState<List | null>(null)
  const [showMobileCreate, setShowMobileCreate] = useState(false)

  // Data fetching
  const { data: lists = [], isLoading: listsLoading } = useLists(user?.id)
  const { data: gearItems = [], isLoading: gearLoading } = useGearItems(user?.id)

  // Mutations
  const createListMutation = useCreateList(user?.id)
  const updateListMutation = useUpdateList(user?.id)
  const deleteListMutation = useDeleteList(user?.id)
  const duplicateListMutation = useDuplicateList(user?.id)

  const handleCreateList = async (data: Omit<List, 'id' | 'user_id' | 'created_at' | 'updated_at'>) => {
    await createListMutation.mutateAsync(data)
  }

  const handleEditList = async (id: string, updates: Partial<Omit<List, 'id' | 'user_id' | 'created_at' | 'updated_at'>>) => {
    await updateListMutation.mutateAsync({ id, updates })
  }

  const handleDeleteList = async (id: string) => {
    await deleteListMutation.mutateAsync(id)
    // If we're viewing the deleted list, go back to list view
    if (selectedList?.id === id) {
      setSelectedList(null)
    }
  }

  const handleDuplicateList = async (listId: string, newName: string) => {
    await duplicateListMutation.mutateAsync({ listId, newName })
  }

  const handleViewList = (list: List) => {
    setSelectedList(list)
  }

  const handleBackToLists = () => {
    setSelectedList(null)
  }

  const isLoading = listsLoading || gearLoading

  if (selectedList) {
    return (
      <div className="min-h-screen bg-background">
        <AppHeader />
        <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6 sm:py-10">
          <div className="mb-6">
            <Button
              variant="ghost"
              onClick={handleBackToLists}
              className="mb-4"
            >
              <ArrowLeft className="w-4 h-4 mr-2" />
              Back to Lists
            </Button>
          </div>

          <ListDetailView
            list={selectedList}
            gearItems={gearItems}
            onEditList={handleEditList}
            onDeleteList={handleDeleteList}
            onBackToLists={handleBackToLists}
          />
        </main>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-background">
      <AppHeader />

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6 sm:py-10">
        {isLoading ? (
          <div className="space-y-6">
            <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
              <div>
                <Skeleton className="h-8 w-48 mb-2" />
                <Skeleton className="h-5 w-64" />
              </div>
              <Skeleton className="h-10 w-32" />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {Array.from({ length: 6 }).map((_, i) => (
                <div key={i} className="border rounded-lg p-6 space-y-4">
                  <Skeleton className="h-32 w-full" />
                  <Skeleton className="h-6 w-3/4" />
                  <Skeleton className="h-4 w-1/2" />
                  <div className="grid grid-cols-3 gap-4">
                    <Skeleton className="h-12 w-full" />
                    <Skeleton className="h-12 w-full" />
                    <Skeleton className="h-12 w-full" />
                  </div>
                  <div className="flex gap-2">
                    <Skeleton className="h-9 flex-1" />
                    <Skeleton className="h-9 w-9" />
                    <Skeleton className="h-9 w-9" />
                    <Skeleton className="h-9 w-9" />
                  </div>
                </div>
              ))}
            </div>
          </div>
        ) : (
          <ListsView
            lists={lists}
            gearItems={gearItems}
            onCreateList={handleCreateList}
            onEditList={handleEditList}
            onDeleteList={handleDeleteList}
            onDuplicateList={handleDuplicateList}
            onViewList={handleViewList}
            loading={createListMutation.isPending || updateListMutation.isPending || deleteListMutation.isPending}
          />
        )}

        {/* Mobile Floating Action Button */}
        <div className="fixed bottom-20 right-6 md:hidden z-50">
          <Button
            size="lg"
            className="rounded-full shadow-lg w-14 h-14 p-0"
            onClick={() => setShowMobileCreate(!showMobileCreate)}
            disabled={isLoading}
          >
            {showMobileCreate ? (
              <ArrowLeft className="h-6 w-6" />
            ) : (
              <Plus className="h-6 w-6" />
            )}
          </Button>
        </div>
      </main>
    </div>
  )
}

import { useState, useMemo } from 'react'
