import type { List, GearItem, WeightUnit } from '@/types/database'

interface ListsViewProps {
  lists: List[]
  gearItems: GearItem[] // All gear items for weight calculations
  weightUnit?: WeightUnit
  onCreateList: (data: Omit<List, 'id' | 'user_id' | 'created_at' | 'updated_at'>) => void
  onEditList: (id: string, updates: Partial<Omit<List, 'id' | 'user_id' | 'created_at' | 'updated_at'>>) => void
  onDeleteList: (id: string) => void
  onDuplicateList: (listId: string, newName: string) => void
  onViewList: (list: List) => void
  loading?: boolean
}

export function ListsView({
  lists,
  gearItems,
  weightUnit = 'g',
  onCreateList,
  onEditList,
  onDeleteList,
  onDuplicateList,
  onViewList,
  loading = false
}: ListsViewProps) {
  const [searchTerm, setSearchTerm] = useState('')
  const [showCreateForm, setShowCreateForm] = useState(false)
  const [editingList, setEditingList] = useState<List | null>(null)
  const [deletingList, setDeletingList] = useState<List | null>(null)

  const handleCreateList = async (data: Omit<List, 'id' | 'user_id' | 'created_at' | 'updated_at'>) => {
    await onCreateList(data)
    setShowCreateForm(false)
  }

  const handleEditList = async (id: string, updates: Partial<Omit<List, 'id' | 'user_id' | 'created_at' | 'updated_at'>>) => {
    await onEditList(id, updates)
    setEditingList(null)
  }

  const handleDeleteList = async (list: List) => {
    await onDeleteList(list.id)
    setDeletingList(null)
  }

  const handleDuplicateList = async (list: List) => {
    const newName = `${list.name} (Copy)`
    await onDuplicateList(list.id, newName)
  }

  // Filter lists based on search term
  const filteredLists = useMemo(() => {
    if (!searchTerm) return lists

    const searchLower = searchTerm.toLowerCase()
    return lists.filter(list =>
      list.name.toLowerCase().includes(searchLower) ||
      list.description?.toLowerCase().includes(searchLower) ||
      list.activity_type?.toLowerCase().includes(searchLower)
    )
  }, [lists, searchTerm])

  if (lists.length === 0 && !loading) {
