          <p className="text-muted-foreground mb-6 max-w-sm mx-auto">
            Create your first list to start organizing gear for different adventures and trips.
          </p>
          <Button
            onClick={() => setShowCreateForm(true)}
            className="bg-primary hover:bg-primary/90"
          >
            <Plus className="w-4 h-4 mr-2" />
            Create Your First List
          </Button>
        </div>

        {/* Create Form */}
        {showCreateForm && (
          <CreateListFormWrapper
            isOpen={showCreateForm}
            onCreate={handleCreateList}
            onCancel={() => setShowCreateForm(false)}
          />
        )}
      </>
    )
  }

  return (
    <>
      <div className="space-y-6">
        {/* Header */}
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
          <div>
            <h2 className="text-2xl font-bold">Your Lists</h2>
          </div>
          <Button
            onClick={() => setShowCreateForm(true)}
            className="bg-primary hover:bg-primary/90"
            disabled={loading}
          >
            <Plus className="w-4 h-4 mr-2" />
            Create List
          </Button>
        </div>

        {/* List Display Header */}
        <ListDisplayHeader
          searchTerm={searchTerm}
          onSearchChange={setSearchTerm}
          searchPlaceholder="Search lists..."
          stats={{
            itemCount: filteredLists.length,
            itemLabel: filteredLists.length !== 1 ? 'lists' : 'list',
            additionalInfo: ' • Organize gear for different adventures'
          }}
        />

        {/* Lists Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredLists.length === 0 && searchTerm ? (
            <div className="col-span-full text-center py-12">
              <Package className="w-12 h-12 text-muted-foreground mx-auto mb-4" />
              <h3 className="text-lg font-medium mb-2">No lists found</h3>
              <p className="text-muted-foreground">
                Try adjusting your search term
              </p>
            </div>
          ) : (
            filteredLists.map((list) => (
              <ListCard
                key={list.id}
                list={list}
                gearItems={gearItems}
                weightUnit={weightUnit}
                onView={onViewList}
                onEdit={setEditingList}
                onDelete={setDeletingList}
                onDuplicate={handleDuplicateList}
              />
            ))
          )}
        </div>
      </div>

      {/* Create Form */}
      {showCreateForm && (
        <CreateListFormWrapper
          isOpen={showCreateForm}
          onCreate={handleCreateList}
          onCancel={() => setShowCreateForm(false)}
        />
      )}

      {/* Edit Form */}
      {editingList && (
        <EditListFormWrapper
          isOpen={!!editingList}
          list={editingList}
          onEdit={handleEditList}
          onCancel={() => setEditingList(null)}
        />
      )}

      {/* Delete Dialog */}
      {deletingList && (
        <DeleteListDialog
          list={deletingList}
          onConfirm={() => handleDeleteList(deletingList)}
          onCancel={() => setDeletingList(null)}
        />
      )}
    </>
  )
}

