  value: string
  label: string
  count?: number
}

interface EmptyStateConfig {
  icon: ReactNode
  title: string
  description: string
  noItemsTitle?: string
  noItemsDescription?: string
  showAddButton?: boolean
  addButtonText?: string
}

interface CollectionPageProps<TItem> {
  // Core data
  items: TItem[]
  filteredItems: TItem[]
  loading: boolean

  // Header configuration
  title: string
