import { useState } from 'react'
import { useAuth } from '@/contexts/AuthContext'
import { AppHeader } from '@/components/navigation/AppHeader'
import { ListsView } from '@/components/lists/ListsView'
import { ListDetailView } from '@/components/lists/ListDetailView'
import { Skeleton } from '@/components/ui/skeleton'
import { Button } from '@/components/ui/button'
import { ArrowLeft, Plus } from 'lucide-react'
import { useLists, useCreateList, useUpdateList, useDeleteList, useDuplicateList } from '@/hooks/useListData'
import { useGearItems } from '@/hooks/useGearData'
import type { List } from '@/types/database'

export function ListPage() {
  const { user } = useAuth()
  const [selectedList, setSelectedList] = useState<List | null>(null)
  const [showMobileCreate, setShowMobileCreate] = useState(false)

  // Data fetching
  const { data: lists = [], isLoading: listsLoading } = useLists(user?.id)
  const { data: gearItems = [], isLoading: gearLoading } = useGearItems(user?.id)

  // Mutations
  const createListMutation = useCreateList(user?.id)
  const updateListMutation = useUpdateList(user?.id)
  const deleteListMutation = useDeleteList(user?.id)
  const duplicateListMutation = useDuplicateList(user?.id)

  const handleCreateList = async (data: Omit<List, 'id' | 'user_id' | 'created_at' | 'updated_at'>) => {
    await createListMutation.mutateAsync(data)
  }

  const handleEditList = async (id: string, updates: Partial<Omit<List, 'id' | 'user_id' | 'created_at' | 'updated_at'>>) => {
    await updateListMutation.mutateAsync({ id, updates })
  }

  const handleDeleteList = async (id: string) => {
    await deleteListMutation.mutateAsync(id)
    // If we're viewing the deleted list, go back to list view
    if (selectedList?.id === id) {
      setSelectedList(null)
    }
  }

  const handleDuplicateList = async (listId: string, newName: string) => {
    await duplicateListMutation.mutateAsync({ listId, newName })
  }

  const handleViewList = (list: List) => {
    setSelectedList(list)
  }

  const handleBackToLists = () => {
    setSelectedList(null)
  }

  const isLoading = listsLoading || gearLoading

  if (selectedList) {
    return (
      <div className="min-h-screen bg-background">
        <AppHeader />
        <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6 sm:py-10">
          <div className="mb-6">
            <Button
              variant="ghost"
              onClick={handleBackToLists}
              className="mb-4"
            >
              <ArrowLeft className="w-4 h-4 mr-2" />
              Back to Lists
            </Button>
          </div>

          <ListDetailView
            list={selectedList}
            gearItems={gearItems}
            onEditList={handleEditList}
            onDeleteList={handleDeleteList}
            onBackToLists={handleBackToLists}
          />
        </main>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-background">
      <AppHeader />

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6 sm:py-10">
        {isLoading ? (
          <div className="space-y-6">
            <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
              <div>
                <Skeleton className="h-8 w-48 mb-2" />
                <Skeleton className="h-5 w-64" />
              </div>
              <Skeleton className="h-10 w-32" />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {Array.from({ length: 6 }).map((_, i) => (
                <div key={i} className="border rounded-lg p-6 space-y-4">
                  <Skeleton className="h-32 w-full" />
                  <Skeleton className="h-6 w-3/4" />
                  <Skeleton className="h-4 w-1/2" />
                  <div className="grid grid-cols-3 gap-4">
                    <Skeleton className="h-12 w-full" />
                    <Skeleton className="h-12 w-full" />
                    <Skeleton className="h-12 w-full" />
                  </div>
                  <div className="flex gap-2">
                    <Skeleton className="h-9 flex-1" />
                    <Skeleton className="h-9 w-9" />
                    <Skeleton className="h-9 w-9" />
                    <Skeleton className="h-9 w-9" />
                  </div>
                </div>
              ))}
            </div>
          </div>
        ) : (
          <ListsView
            lists={lists}
            gearItems={gearItems}
            onCreateList={handleCreateList}
            onEditList={handleEditList}
            onDeleteList={handleDeleteList}
            onDuplicateList={handleDuplicateList}
            onViewList={handleViewList}
            loading={createListMutation.isPending || updateListMutation.isPending || deleteListMutation.isPending}
          />
        )}

        {/* Mobile Floating Action Button */}
        <div className="fixed bottom-20 right-6 md:hidden z-50">
          <Button
            size="lg"
            className="rounded-full shadow-lg w-14 h-14 p-0"
            onClick={() => setShowMobileCreate(!showMobileCreate)}
            disabled={isLoading}
          >
            {showMobileCreate ? (
              <ArrowLeft className="h-6 w-6" />
            ) : (
              <Plus className="h-6 w-6" />
            )}
          </Button>
        </div>
      </main>
    </div>
  )
}

