import { Button } from '@/components/ui/button'
import { 
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { TableProperties, LayoutList, LayoutGrid } from 'lucide-react'
import type { ViewMode } from '@/pages/GearCloset'

interface ViewModeSelectorProps {
  value: ViewMode
  onChange: (mode: ViewMode) => void
}

export function ViewModeSelector({ value, onChange }: ViewModeSelectorProps) {
  const modes: { value: ViewMode; label: string; icon: React.ReactNode; description: string }[] = [
    {
      value: 'compact',
      label: 'Compact',
      icon: <TableProperties className="h-4 w-4" />,
      description: 'Spreadsheet-style view with minimal spacing'
    },
    {
      value: 'default',
      label: 'Default',
      icon: <LayoutList className="h-4 w-4" />,
      description: 'Balanced view with essential information'
    },
    {
      value: 'comfortable',
      label: 'Comfortable',
      icon: <LayoutGrid className="h-4 w-4" />,
      description: 'Card view with rich details and visuals'
    }
  ]

  const currentMode = modes.find(m => m.value === value) || modes[1]

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button variant="outline" size="sm" className="gap-2 min-h-[44px]">
          {currentMode.icon}
          <span className="ml-2">{currentMode.label}</span>
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="w-64">
        {modes.map(mode => (
          <DropdownMenuItem
            key={mode.value}
            onClick={() => onChange(mode.value)}
            className="flex flex-col items-start py-3 cursor-pointer"
          >
            <div className="flex items-center space-x-2 mb-1">
              {mode.icon}
              <span className="font-medium">{mode.label}</span>
              {mode.value === value && (
                <span className="ml-auto text-xs bg-primary/10 text-primary px-2 py-0.5 rounded">
                  Active
                </span>
              )}
            </div>
            <span className="text-xs text-muted-foreground">
              {mode.description}
            </span>
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

import { memo, useMemo } from 'react'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { 
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { Edit2, Trash2, MoreHorizontal, Copy, ChevronUp, ChevronDown, ChevronsUpDown, FileText } from 'lucide-react'
import type { GearItem, WeightUnit } from '@/types/database'
import { formatWeightWithUnit } from '@/utils/weight'
import type { ViewMode } from '@/pages/GearCloset'

export type SortField = 'name' | 'category' | 'weight_grams' | 'quantity' | 'total'
export type SortDirection = 'asc' | 'desc'

interface GearTableProps {
  items: GearItem[]
  viewMode: ViewMode
  weightUnit?: WeightUnit
  onEdit: (item: GearItem) => void
  onDelete: (item: GearItem) => void
  sortField?: SortField
  sortDirection?: SortDirection
  onSort?: (field: SortField) => void
}

export const GearTable = memo(function GearTable({ 
  items, 
  viewMode, 
  weightUnit = 'g',
  onEdit, 
  onDelete, 
  sortField,
  sortDirection,
  onSort 
}: GearTableProps) {
  const isCompact = viewMode === 'compact'

  // Memoize summary calculations
  const { totalWeight, totalQuantity, totalCombinedWeight } = useMemo(() => ({
    totalWeight: items.reduce((sum, item) => sum + item.weight_grams, 0),
    totalQuantity: items.reduce((sum, item) => sum + item.quantity, 0),
    totalCombinedWeight: items.reduce((sum, item) => sum + (item.weight_grams * item.quantity), 0)
  }), [items])

  const getSortIcon = (field: SortField) => {
    if (sortField !== field) {
      return <ChevronsUpDown className="ml-1 h-3 w-3 text-muted-foreground/50" />
    }
    return sortDirection === 'asc' 
      ? <ChevronUp className="ml-1 h-3 w-3" />
      : <ChevronDown className="ml-1 h-3 w-3" />
  }

  return (
    <div className="bg-white rounded-lg border border-border/40 overflow-hidden">
      <Table>
        <TableHeader>
          <TableRow className={isCompact ? 'h-8' : 'h-10'}>
            <TableHead 
              className={`${isCompact ? 'text-xs' : 'text-sm'} font-medium cursor-pointer hover:bg-accent/50`}
              onClick={() => onSort?.('name')}
            >
              <div className="flex items-center">
                Item
                {getSortIcon('name')}
              </div>
            </TableHead>
            <TableHead 
