            >
              <div className="flex items-center justify-end">
                Weight
                {getSortIcon('weight_grams')}
              </div>
            </TableHead>
            <TableHead 
              className={`${isCompact ? 'text-xs' : 'text-sm'} font-medium text-right cursor-pointer hover:bg-accent/50 hidden sm:table-cell`}
              onClick={() => onSort?.('quantity')}
            >
              <div className="flex items-center justify-end">
                Qty
                {getSortIcon('quantity')}
              </div>
            </TableHead>
            <TableHead 
              className={`${isCompact ? 'text-xs' : 'text-sm'} font-medium text-right cursor-pointer hover:bg-accent/50 hidden md:table-cell`}
              onClick={() => onSort?.('total')}
            >
              <div className="flex items-center justify-end">
                Total
                {getSortIcon('total')}
              </div>
            </TableHead>
            {!isCompact && (
              <TableHead className="text-sm font-medium hidden sm:table-cell">
                Properties
              </TableHead>
            )}
            <TableHead className="text-right">
              <span className="sr-only">Actions</span>
            </TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {items.map((item) => (
            <TableRow 
              key={item.id} 
              className={`hover:bg-accent/50 transition-colors ${
                isCompact ? 'h-10' : 'h-14'
              }`}
            >
              <TableCell className={isCompact ? 'py-1' : 'py-2'}>
                <div className={isCompact ? 'space-y-0' : 'space-y-1'}>
                  <div className={`${isCompact ? 'text-sm' : 'text-base'}`}>
                    {item.name}
                  </div>
                  {(item.model || item.description) && (
                    <div className={`text-muted-foreground ${isCompact ? 'text-xs' : 'text-sm'}`}>
                      {item.model || item.description}
                    </div>
                  )}
                  {!isCompact && item.brand && (
                    <div className="text-xs text-muted-foreground">
                      {item.brand}
                    </div>
                  )}
                  {/* Mobile-only: Show category, weight, and properties inline */}
                  <div className="sm:hidden text-xs text-muted-foreground mt-1">
                    {item.category} • {formatWeightWithUnit(item.weight_grams, weightUnit)}
                    {item.worn && <span> • Worn</span>}
                    {item.consumable && <span> • Consumable</span>}
                  </div>
                </div>
              </TableCell>
              <TableCell className={`${isCompact ? 'py-1' : 'py-2'} hidden sm:table-cell`}>
                <Badge variant="outline" className={isCompact ? 'text-xs py-0' : ''}>
                  {item.category}
                </Badge>
              </TableCell>
              <TableCell className={`text-right ${isCompact ? 'py-1 text-sm' : 'py-2'} hidden sm:table-cell`}>
                {formatWeightWithUnit(item.weight_grams, weightUnit)}
              </TableCell>
              <TableCell className={`text-right ${isCompact ? 'py-1 text-sm' : 'py-2'} hidden sm:table-cell`}>
                {item.quantity}
              </TableCell>
              <TableCell className={`text-right font-medium ${isCompact ? 'py-1 text-sm' : 'py-2'} hidden md:table-cell`}>
                {formatWeightWithUnit(item.weight_grams * item.quantity, weightUnit)}
              </TableCell>
              {!isCompact && (
                <TableCell className="py-2 hidden sm:table-cell">
                  <div className="flex items-center gap-1">
                    {item.worn && (
                      <Badge variant="secondary" className="text-xs">
                        Worn
                      </Badge>
                    )}
                    {item.consumable && (
                      <Badge variant="secondary" className="text-xs">
                        Consumable
                      </Badge>
                    )}
                    {item.notes ? (
                      <div className="group relative">
                        <FileText className="h-3 w-3 text-muted-foreground cursor-help" />
                        <div className="absolute z-10 hidden group-hover:block bottom-full left-0 mb-2 w-64 p-2 bg-popover text-popover-foreground text-xs rounded-md shadow-md border">
                          {item.notes}
                        </div>
                      </div>
                    ) : null}
                  </div>
                </TableCell>
              )}
              <TableCell className={`text-right ${isCompact ? 'py-1' : 'py-2'}`}>
                <DropdownMenu>
                  <DropdownMenuTrigger asChild>
                    <Button
                      variant="ghost"
                      size={isCompact ? 'sm' : 'default'}
                      className="h-8 w-8 p-0"
                    >
                      <span className="sr-only">Open menu</span>
                      <MoreHorizontal className={isCompact ? 'h-3 w-3' : 'h-4 w-4'} />
                    </Button>
                  </DropdownMenuTrigger>
                  <DropdownMenuContent align="end">
                    <DropdownMenuItem 
                      onClick={() => onEdit(item)}
                      className="cursor-pointer"
                    >
                      <Edit2 className="mr-2 h-4 w-4" />
                      Edit
                    </DropdownMenuItem>
                    <DropdownMenuItem 
                      onClick={() => {
                        // Clone functionality - use object destructuring for type safety
                        const { id, created_at, updated_at, user_id, ...cloneData } = item
                        // Create a new item with the cloned data
                        const newItem: Omit<GearItem, 'id' | 'created_at' | 'updated_at' | 'user_id'> = cloneData
                        // Since we're using onEdit for duplicate, we need to pass a full GearItem
                        // The parent will handle this as a create operation
                        onEdit({ ...newItem, name: `${newItem.name} (Copy)` } as GearItem)
                      }}
                      className="cursor-pointer"
                    >
                      <Copy className="mr-2 h-4 w-4" />
                      Duplicate
                    </DropdownMenuItem>
                    <DropdownMenuSeparator />
                    <DropdownMenuItem
                      onClick={() => onDelete(item)}
                      className="cursor-pointer text-destructive focus:text-destructive"
                    >
                      <Trash2 className="mr-2 h-4 w-4" />
                      Delete
                    </DropdownMenuItem>
                  </DropdownMenuContent>
                </DropdownMenu>
              </TableCell>
            </TableRow>
          ))}
          {/* Summary Row */}
          {items.length > 0 && (
            <TableRow className="bg-muted/50 border-t-2 font-medium">
              <TableCell className={`${isCompact ? 'py-2 text-sm' : 'py-3'}`}>
                Total ({items.length} items)
              </TableCell>
              <TableCell className="hidden sm:table-cell" />
              <TableCell className={`text-right ${isCompact ? 'py-2 text-sm' : 'py-3'} hidden sm:table-cell`}>
                {formatWeightWithUnit(totalWeight, weightUnit)}
              </TableCell>
              <TableCell className={`text-right ${isCompact ? 'py-2 text-sm' : 'py-3'} hidden sm:table-cell`}>
                {totalQuantity}
              </TableCell>
              <TableCell className={`text-right font-semibold ${isCompact ? 'py-2 text-sm' : 'py-3'} hidden md:table-cell`}>
                {formatWeightWithUnit(totalCombinedWeight, weightUnit)}
              </TableCell>
              {!isCompact && <TableCell className="hidden sm:table-cell" />}
              <TableCell />
            </TableRow>
          )}
        </TableBody>
      </Table>
    </div>
  )
})

import { useState, useMemo, useCallback } from 'react'
import { useAuth } from '@/contexts/AuthContext'
import { ListsView } from '@/components/lists/ListsView'
import { ListDetailView } from '@/components/lists/ListDetailView'
import { CollectionPage } from '@/components/shared/CollectionPage'
import { Button } from '@/components/ui/button'
import { ArrowLeft, Package } from 'lucide-react'
import { useLists, useCreateList, useUpdateList, useDeleteList, useDuplicateList } from '@/hooks/useListData'
import { useGearItems } from '@/hooks/useGearData'
import type { List } from '@/types/database'

export function ListPage() {
  const { user } = useAuth()
  const [selectedList, setSelectedList] = useState<List | null>(null)
  const [searchTerm, setSearchTerm] = useState('')

  // Data fetching
  const { data: lists = [], isLoading: listsLoading } = useLists(user?.id)
  const { data: gearItems = [], isLoading: gearLoading } = useGearItems(user?.id)

  // Mutations
  const createListMutation = useCreateList(user?.id)
  const updateListMutation = useUpdateList(user?.id)
  const deleteListMutation = useDeleteList(user?.id)
  const duplicateListMutation = useDuplicateList(user?.id)

  const handleCreateList = async (data: Omit<List, 'id' | 'user_id' | 'created_at' | 'updated_at'>) => {
    await createListMutation.mutateAsync(data)
  }

  const handleEditList = async (id: string, updates: Partial<Omit<List, 'id' | 'user_id' | 'created_at' | 'updated_at'>>) => {
    await updateListMutation.mutateAsync({ id, updates })
  }

  const handleDeleteList = async (id: string) => {
    await deleteListMutation.mutateAsync(id)
    // If we're viewing the deleted list, go back to list view
    if (selectedList?.id === id) {
      setSelectedList(null)
    }
  }

  const handleDuplicateList = async (listId: string, newName: string) => {
    await duplicateListMutation.mutateAsync({ listId, newName })
  }

  const handleViewList = (list: List) => {
    setSelectedList(list)
  }

  const handleBackToLists = () => {
    setSelectedList(null)
  }

  // Filter lists based on search term
  const filteredLists = useMemo(() => {
    if (!searchTerm) return lists

    const searchLower = searchTerm.toLowerCase()
    return lists.filter(list =>
      list.name.toLowerCase().includes(searchLower) ||
      list.description?.toLowerCase().includes(searchLower) ||
      list.activity_type?.toLowerCase().includes(searchLower)
    )
  }, [lists, searchTerm])

  const isLoading = listsLoading || gearLoading

  if (selectedList) {
    return (
      <div className="min-h-screen bg-background">
        <AppHeader />
        <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6 sm:py-10">
          <div className="mb-6">
            <Button
              variant="ghost"
              onClick={handleBackToLists}
              className="mb-4"
            >
              <ArrowLeft className="w-4 h-4 mr-2" />
              Back to Lists
            </Button>
          </div>

          <ListDetailView
            list={selectedList}
            gearItems={gearItems}
            onEditList={handleEditList}
            onDeleteList={handleDeleteList}
            onBackToLists={handleBackToLists}
          />
        </main>
      </div>
    )
  }

  // Use ListsView component for collection display
  if (selectedList) {
    return (
      <div className="min-h-screen bg-background">
        <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6 sm:py-10">
          <div className="mb-6">
            <Button
              variant="ghost"
              onClick={handleBackToLists}
              className="mb-4"
            >
              <ArrowLeft className="w-4 h-4 mr-2" />
              Back to Lists
            </Button>
          </div>

          <ListDetailView
            list={selectedList}
            gearItems={gearItems}
            onEditList={handleEditList}
            onDeleteList={handleDeleteList}
            onBackToLists={handleBackToLists}
          />
        </main>
      </div>
    )
  }

  return (
    <ListsView
      lists={lists}
      gearItems={gearItems}
      onCreateList={handleCreateList}
      onEditList={handleEditList}
      onDeleteList={handleDeleteList}
      onDuplicateList={handleDuplicateList}
      onViewList={handleViewList}
      loading={createListMutation.isPending || updateListMutation.isPending || deleteListMutation.isPending}
    />
  )
}

