import { GearItem } from '@/types/database'

interface GearListProps {
  items: GearItem[]
}

export function GearList({ items }: GearListProps) {
  const totalWeight = items.reduce((sum, item) => sum + (item.weight_grams * item.quantity), 0)

  return (
    <div className="bg-white rounded-lg shadow">
      <div className="p-4 border-b">
        <h2 className="text-xl font-semibold">Your Gear</h2>
        <p className="text-sm text-gray-600 mt-1">
          Total weight: {totalWeight}g ({(totalWeight / 1000).toFixed(2)}kg)
        </p>
      </div>
      <div className="divide-y">
        {items.length === 0 ? (
          <p className="p-4 text-gray-500">No gear added yet</p>
        ) : (
          items.map((item) => (
            <div key={item.id} className="p-4 hover:bg-gray-50">
              <div className="flex justify-between items-start">
                <div>
                  <h3 className="font-medium">{item.name}</h3>
                  <p className="text-sm text-gray-600">
                    {item.weight_grams}g × {item.quantity} = {item.weight_grams * item.quantity}g
                  </p>
                  {item.notes && (
                    <p className="text-sm text-gray-500 mt-1">{item.notes}</p>
                  )}
                </div>
                <div className="flex gap-2">
                  <span className="text-xs bg-gray-100 px-2 py-1 rounded">
                    {item.category}
                  </span>
                  {item.worn && (
                    <span className="text-xs bg-blue-100 text-blue-700 px-2 py-1 rounded">
                      Worn
                    </span>
                  )}
                  {item.consumable && (
                    <span className="text-xs bg-green-100 text-green-700 px-2 py-1 rounded">
                      Consumable
                    </span>
                  )}
                </div>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  )
}

