import { Button } from '@/components/ui/button'
import { 
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { TableProperties, LayoutList, LayoutGrid } from 'lucide-react'
import type { ViewMode } from '@/pages/GearPage'

interface ViewModeSelectorProps {
  value: ViewMode
  onChange: (mode: ViewMode) => void
}

export function ViewModeSelector({ value, onChange }: ViewModeSelectorProps) {
  const modes: { value: ViewMode; label: string; icon: React.ReactNode; description: string }[] = [
    {
      value: 'compact',
      label: 'Compact',
      icon: <TableProperties className="h-4 w-4" />,
      description: 'Spreadsheet-style view with minimal spacing'
    },
    {
      value: 'default',
      label: 'Default',
      icon: <LayoutList className="h-4 w-4" />,
      description: 'Balanced view with essential information'
    },
    {
      value: 'comfortable',
      label: 'Comfortable',
      icon: <LayoutGrid className="h-4 w-4" />,
      description: 'Card view with rich details and visuals'
    }
  ]

  const currentMode = modes.find(m => m.value === value) || modes[1]

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button variant="outline" size="sm" className="gap-2 min-h-[44px]">
          {currentMode.icon}
          <span className="ml-2">{currentMode.label}</span>
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="w-64">
        {modes.map(mode => (
          <DropdownMenuItem
            key={mode.value}
            onClick={() => onChange(mode.value)}
            className="flex flex-col items-start py-3 cursor-pointer"
          >
            <div className="flex items-center space-x-2 mb-1">
              {mode.icon}
              <span className="font-medium">{mode.label}</span>
              {mode.value === value && (
                <span className="ml-auto text-xs bg-primary/10 text-primary px-2 py-0.5 rounded">
                  Active
                </span>
              )}
            </div>
            <span className="text-xs text-muted-foreground">
              {mode.description}
            </span>
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

