import { ReactNode } from 'react'
import { Button } from '@/components/ui/button'
import { 
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'

interface ViewModeOption {
  value: string
  label: string
  icon: ReactNode
  description: string
}

interface ViewModeSelectorProps {
  value: string
  onChange: (mode: string) => void
  options: ViewModeOption[]
}

export function ViewModeSelector({ value, onChange, options }: ViewModeSelectorProps) {
  const currentMode = options.find(m => m.value === value) || options[0]

  return (
    <>
      {/* Mobile: Single cycling button */}
      <Button
        variant="outline"
        className="justify-center min-h-[44px] min-w-[44px] sm:hidden"
        onClick={() => {
          const currentIndex = options.findIndex(opt => opt.value === value)
          const nextIndex = (currentIndex + 1) % options.length
          onChange(options[nextIndex].value)
        }}
      >
        {currentMode.icon}
      </Button>

      {/* Desktop: Dropdown menu */}
      <div className="hidden sm:flex">
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button variant="outline" size="sm" className="gap-2 min-h-[44px]">
              {currentMode.icon}
              <span className="ml-2">{currentMode.label}</span>
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end" className="w-64">
            {options.map(mode => (
              <DropdownMenuItem
                key={mode.value}
                onClick={() => onChange(mode.value)}
                className="flex flex-col items-start py-3 cursor-pointer"
              >
                <div className="flex items-center space-x-2 mb-1">
                  {mode.icon}
                  <span className="font-medium">{mode.label}</span>
                  {mode.value === value && (
                    <span className="ml-auto text-xs bg-primary/10 text-primary px-2 py-0.5 rounded">
                      Active
                    </span>
                  )}
                </div>
                <span className="text-xs text-muted-foreground">
                  {mode.description}
                </span>
              </DropdownMenuItem>
            ))}
          </DropdownMenuContent>
        </DropdownMenu>
      </div>
    </>
  )
}

